-- =============================================================================
-- 0001 · Extensions, enum types and generic utility functions
-- Suntec+ Play & Win — gamification platform
--
-- Safe to re-run: every statement is idempotent.
-- Conventions used across all migrations:
--   * Timestamps are timestamptz (UTC). Business days are `date` in the configured
--     timezone (app_settings.timezone, default Asia/Singapore).
--   * Money is stored in integer cents (SGD).
--   * Probability weights are integer basis points (10000 = 100%).
--   * Customer-visible references (GS-…, RT-…) are generated by gen_public_ref().
-- =============================================================================

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;   -- gen_random_bytes / digest (secure RNG, hashing)
create extension if not exists citext   with schema extensions;   -- case-insensitive emails

