-- =============================================================================
-- 0003 · Segments, eligibility rules, merchants, campaigns
-- =============================================================================

-- -----------------------------------------------------------------------------
-- segments — target customer segments, defined as declarative rules evaluated
-- against member attributes (tier, tags, join date, engagement counters).
-- Rule format (validated by Zod in packages/core):
--   {"all":[{"field":"tier","op":"in","value":["gold","platinum"]},
--           {"field":"joined_days","op":"lte","value":90}]}
-- -----------------------------------------------------------------------------
create table if not exists public.segments (
  id           uuid primary key default gen_random_uuid(),
  key          text not null,
  name         text not null,
  description  text not null default '',
  rules        jsonb not null default '{"all":[]}',
  status       public.record_status not null default 'active',
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint segments_key_key unique (key),
  constraint segments_rules_is_object check (jsonb_typeof(rules) = 'object')
);
comment on table public.segments is 'Target customer segments as declarative rules (tier, tags, join date, engagement). Evaluated by the engine.';

-- -----------------------------------------------------------------------------
-- eligibility_rules — reusable participation conditions attached to campaigns,
-- games, missions, rewards and check-in programmes. Same rule grammar as segments,
-- plus optional segment references: {"segments_any":["<uuid>"], "all":[...]}
-- -----------------------------------------------------------------------------
create table if not exists public.eligibility_rules (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  description  text not null default '',
  rules        jsonb not null default '{"all":[]}',
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint eligibility_rules_rules_is_object check (jsonb_typeof(rules) = 'object')
);
comment on table public.eligibility_rules is 'Reusable eligibility conditions (tier, new vs existing, segments, dates) referenced by campaigns, games, missions and rewards.';

-- -----------------------------------------------------------------------------
-- merchants — participating Suntec City tenants (for spend/visit missions and
-- merchant vouchers). merchant_code is the id used by the transaction system.
-- -----------------------------------------------------------------------------
create table if not exists public.merchants (
  id              uuid primary key default gen_random_uuid(),
  merchant_code   text not null,
  name            text not null,
  category        text not null default 'retail',
  unit_no         text,
  logo_path       text,
  is_participating boolean not null default true,
  status          public.record_status not null default 'active',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint merchants_code_key unique (merchant_code)
);
comment on table public.merchants is 'Suntec City tenants. Participating merchants count towards spend/visit missions and can fund merchant vouchers.';
create index if not exists merchants_participating_idx on public.merchants (is_participating) where status = 'active';

-- -----------------------------------------------------------------------------
-- campaigns — container for games, missions, check-in programmes, rewards and
-- leaderboards, with schedule, audience, priority and participation limits.
-- limits: {"per_day":5,"per_week":20,"per_campaign":100,"cooldown_seconds":30}
-- -----------------------------------------------------------------------------
create table if not exists public.campaigns (
  id                  uuid primary key default gen_random_uuid(),
  slug                text not null,
  name                text not null,
  description         text not null default '',
  banner_path         text,                               -- Supabase Storage path (bucket: public-assets)
  theme               jsonb not null default '{}',        -- optional colour/imagery overrides
  priority            int  not null default 100,          -- lower = shown first
  status              public.lifecycle_status not null default 'draft',
  starts_at           timestamptz,
  ends_at             timestamptz,
  eligibility_rule_id uuid references public.eligibility_rules (id) on delete set null,
  limits              jsonb not null default '{}',
  terms               text not null default '',
  preview_token_hash  text,                               -- signed preview link (hash only)
  published_at        timestamptz,
  created_by          uuid references auth.users (id) on delete set null,
  updated_by          uuid references auth.users (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint campaigns_slug_key unique (slug),
  constraint campaigns_dates_chk check (ends_at is null or starts_at is null or ends_at > starts_at),
  constraint campaigns_limits_is_object check (jsonb_typeof(limits) = 'object')
);
comment on table public.campaigns is 'Marketing campaign: schedule (SGT), target segments, eligibility, priority, participation limits. Groups games, missions, rewards and leaderboards.';
create index if not exists campaigns_live_idx on public.campaigns (status, starts_at, ends_at);
create index if not exists campaigns_priority_idx on public.campaigns (priority) where status = 'active';

create table if not exists public.campaign_segments (
  campaign_id  uuid not null references public.campaigns (id) on delete cascade,
  segment_id   uuid not null references public.segments (id) on delete cascade,
  primary key (campaign_id, segment_id)
);
comment on table public.campaign_segments is 'Target segments for a campaign (empty = all members).';
create index if not exists campaign_segments_segment_idx on public.campaign_segments (segment_id);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0004_rewards.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0004 · Reward catalogue & inventory
-- =============================================================================

create table if not exists public.reward_categories (
  id          uuid primary key default gen_random_uuid(),
  key         text not null,
  name        text not null,
  description text not null default '',
  icon        text,
  sort        int  not null default 100,
  status      public.record_status not null default 'active',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint reward_categories_key_key unique (key)
);
comment on table public.reward_categories is 'Reward catalogue categories (Dining, Retail, Suntec+ Points, Gifts, Privileges…).';

-- -----------------------------------------------------------------------------
-- rewards — every prize/reward the platform can allocate (game outcomes, mission,
-- check-in, badge and leaderboard rewards, catalogue redemptions).
-- `value` depends on `type`:
--   play_points      {"amount": 50}
--   bonus_attempt    {"count": 1, "game_id": null}          (null = same game that awarded it)
--   capillary_points {"points": 500}                        (awarded in Capillary via API)
--   digital_voucher  {"series_id": "DIN5", "face_value_cents": 500}
--   merchant_voucher {"merchant_id": "…", "source": "code_pool"|"vms", "series_id": "…", "face_value_cents": 1000}
--   promo_gift       {"collect_at": "Concierge, Tower 3 Level 1"}
--   exclusive_reward {"fulfilment": "code_pool"|"manual"}
--   privilege        {"duration_days": 30, "benefit": "VIP lounge access"}
--   none             {}
-- -----------------------------------------------------------------------------
create table if not exists public.rewards (
  id                  uuid primary key default gen_random_uuid(),
  category_id         uuid references public.reward_categories (id) on delete set null,
  campaign_id         uuid references public.campaigns (id) on delete set null,   -- null = platform-wide
  key                 text not null,
  type                public.reward_type not null,
  name                text not null,
  description         text not null default '',
  image_path          text,
  value               jsonb not null default '{}',
  unit_cost_cents     int  not null default 0 check (unit_cost_cents >= 0),        -- business cost, used by simulator & reports
  in_catalogue        boolean not null default false,                              -- redeemable with Play Points
  pp_cost             int check (pp_cost is null or pp_cost > 0),
  eligibility_rule_id uuid references public.eligibility_rules (id) on delete set null,
  validity_days       int check (validity_days is null or validity_days > 0),      -- expiry relative to issue
  valid_until         timestamptz,                                                 -- or a fixed expiry date
  per_member_cap      int check (per_member_cap is null or per_member_cap > 0),
  per_member_period   public.recurrence not null default 'once',                   -- window for per_member_cap
  terms               text not null default '',
  sort                int not null default 100,
  status              public.record_status not null default 'active',
  created_by          uuid references auth.users (id) on delete set null,
  updated_by          uuid references auth.users (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint rewards_key_key unique (key),
  constraint rewards_value_is_object check (jsonb_typeof(value) = 'object'),
  constraint rewards_catalogue_needs_cost check (not in_catalogue or pp_cost is not null)
);
comment on table public.rewards is 'Reward definitions: Play Points, bonus attempts, Capillary points, vouchers, gifts, privileges. Catalogue items carry a Play Points price.';
create index if not exists rewards_catalogue_idx on public.rewards (category_id, sort) where in_catalogue and status = 'active';
create index if not exists rewards_campaign_idx on public.rewards (campaign_id);

-- -----------------------------------------------------------------------------
-- reward_inventory — stock per reward. NULL total_qty = unlimited.
-- remaining_qty is decremented under SELECT … FOR UPDATE by the engine.
-- -----------------------------------------------------------------------------
create table if not exists public.reward_inventory (
  reward_id           uuid primary key references public.rewards (id) on delete cascade,
  total_qty           int check (total_qty is null or total_qty >= 0),
  remaining_qty       int check (remaining_qty is null or remaining_qty >= 0),
  daily_cap           int check (daily_cap is null or daily_cap >= 0),
  low_stock_threshold int not null default 0,
  updated_at          timestamptz not null default now(),
  constraint reward_inventory_unlimited_chk check ((total_qty is null) = (remaining_qty is null)),
  constraint reward_inventory_le_total_chk  check (remaining_qty is null or remaining_qty <= total_qty)
);
comment on table public.reward_inventory is 'Stock & daily cap per reward (NULL = unlimited). Locked row-by-row during allocation to prevent overselling.';

-- Daily issued counter per reward (enforces daily_cap without scanning transactions).
create table if not exists public.reward_inventory_daily (
  reward_id  uuid not null references public.rewards (id) on delete cascade,
  day        date not null,
  issued     int  not null default 0 check (issued >= 0),
  primary key (reward_id, day)
);
comment on table public.reward_inventory_daily is 'Per-day issued counter per reward, for daily caps.';

-- Pre-loaded unique codes for merchant / exclusive rewards fulfilled from a code pool.
create table if not exists public.voucher_code_pool (
  id               uuid primary key default gen_random_uuid(),
  reward_id        uuid not null references public.rewards (id) on delete cascade,
  code             text not null,
  status           text not null default 'available' check (status in ('available', 'assigned', 'void')),
  assigned_txn_id  uuid,
  assigned_at      timestamptz,
  expires_at       timestamptz,
  created_at       timestamptz not null default now(),
  constraint voucher_code_pool_code_key unique (reward_id, code)
);
comment on table public.voucher_code_pool is 'Unique voucher codes uploaded by admins for code-pool rewards; assigned atomically with FOR UPDATE SKIP LOCKED.';
create index if not exists voucher_code_pool_available_idx on public.voucher_code_pool (reward_id, created_at) where status = 'available';


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0005_games.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0005 · Games: type registry, configuration, outcomes, quiz bank, sessions,
--        earned attempts
-- =============================================================================

-- -----------------------------------------------------------------------------
-- game_types — registry of game engines. New game types are added here plus a
-- resolver in the engine; the rest of the schema is generic.
-- -----------------------------------------------------------------------------
create table if not exists public.game_types (
  key            text primary key,
  name           text not null,
  description    text not null default '',
  weighted       boolean not null,     -- outcome drawn from weighted game_outcomes (spin, scratch)
  has_questions  boolean not null,     -- uses quiz_questions (quiz)
  enabled        boolean not null default true
);
comment on table public.game_types is 'Registry of game engines (spin_wheel, scratch_card, quiz). Extensible: add a row + an engine resolver.';

insert into public.game_types (key, name, description, weighted, has_questions) values
  ('spin_wheel',   'Spin & Win',    'Configurable prize wheel; outcome drawn server-side by weight', true,  false),
  ('scratch_card', 'Scratch & Win', 'Digital scratch card; outcome drawn server-side at card issue', true,  false),
  ('quiz',         'Quiz & Trivia', 'Timed multiple-choice quiz; scored server-side',                 false, true)
on conflict (key) do update set name = excluded.name, description = excluded.description,
  weighted = excluded.weighted, has_questions = excluded.has_questions;

-- -----------------------------------------------------------------------------
-- games — a configured game inside a campaign.
-- attempt_rules: {"free_per_day":1,"pp_cost":200,"max_per_day":5,"max_per_week":null,
--                 "max_per_campaign":null,"cooldown_seconds":30,"session_ttl_seconds":120}
-- config (per type):
--   spin_wheel   {"spin_duration_ms":4500}
--   scratch_card {"reveal_threshold":0.6,"cover_image":"…"}
--   quiz         {"questions_per_session":5,"time_limit_s":20,"pass_percent":60,"speed_bonus":true,
--                 "shuffle":true,"reward_tiers":[{"min_correct":5,"reward_id":"…"},{"min_correct":3,"reward_id":"…"}]}
-- -----------------------------------------------------------------------------
create table if not exists public.games (
  id                  uuid primary key default gen_random_uuid(),
  campaign_id         uuid references public.campaigns (id) on delete cascade,
  type                text not null references public.game_types (key),
  slug                text not null,
  name                text not null,
  description         text not null default '',
  banner_path         text,
  status              public.lifecycle_status not null default 'draft',
  priority            int  not null default 100,
  starts_at           timestamptz,
  ends_at             timestamptz,
  eligibility_rule_id uuid references public.eligibility_rules (id) on delete set null,
  attempt_rules       jsonb not null default '{"free_per_day":1,"max_per_day":3,"cooldown_seconds":10,"session_ttl_seconds":180}',
  config              jsonb not null default '{}',
  rules_text          text not null default '',          -- customer-facing rules / T&Cs
  created_by          uuid references auth.users (id) on delete set null,
  updated_by          uuid references auth.users (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint games_slug_key unique (slug),
  constraint games_dates_chk check (ends_at is null or starts_at is null or ends_at > starts_at),
  constraint games_attempt_rules_is_object check (jsonb_typeof(attempt_rules) = 'object'),
  constraint games_config_is_object check (jsonb_typeof(config) = 'object')
);
comment on table public.games is 'A configured game (spin, scratch, quiz) with schedule, eligibility, attempt limits/cost and type-specific config.';
create index if not exists games_campaign_idx on public.games (campaign_id, status);
create index if not exists games_live_idx on public.games (status, starts_at, ends_at);

-- -----------------------------------------------------------------------------
-- game_outcomes — weighted outcomes for spin wheels (segments) and scratch cards.
-- weight_bp: basis points; an ACTIVE weighted game must total exactly 10000 (100%).
-- display: {"color":"#F97316","text_color":"#1F2937","icon":"gift","image":"…"}
-- -----------------------------------------------------------------------------
create table if not exists public.game_outcomes (
  id                  uuid primary key default gen_random_uuid(),
  game_id             uuid not null references public.games (id) on delete cascade,
  position            int  not null check (position >= 0),
  label               text not null,
  display             jsonb not null default '{}',
  reward_id           uuid references public.rewards (id) on delete restrict,   -- null = no prize ("Try again")
  reward_qty          int  not null default 1 check (reward_qty > 0),
  weight_bp           int  not null check (weight_bp between 0 and 10000),
  fallback_strategy   public.fallback_strategy not null default 'renormalize',
  fallback_outcome_id uuid references public.game_outcomes (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint game_outcomes_position_key unique (game_id, position),
  constraint game_outcomes_fallback_chk check (fallback_strategy <> 'outcome' or fallback_outcome_id is not null),
  constraint game_outcomes_not_self_fallback check (fallback_outcome_id is null or fallback_outcome_id <> id)
);
comment on table public.game_outcomes is 'Weighted outcomes (wheel segments / scratch prizes). Weights in basis points must total 100% for an active game. Weights are NEVER sent to clients.';
create index if not exists game_outcomes_reward_idx on public.game_outcomes (reward_id);

-- -----------------------------------------------------------------------------
-- Quiz question bank (per game). Correct answers never leave the server.
-- -----------------------------------------------------------------------------
create table if not exists public.quiz_questions (
  id            uuid primary key default gen_random_uuid(),
  game_id       uuid not null references public.games (id) on delete cascade,
  category      text not null default 'general',          -- suntec | merchants | campaign | general
  text          text not null,
  image_path    text,
  explanation   text not null default '',
  time_limit_s  int  check (time_limit_s is null or time_limit_s between 5 and 300),  -- overrides game default
  points        int  not null default 100 check (points >= 0),
  status        public.record_status not null default 'active',
  sort          int  not null default 100,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
comment on table public.quiz_questions is 'Quiz & Trivia question bank per game. Sessions sample questions from here.';
create index if not exists quiz_questions_game_idx on public.quiz_questions (game_id, status);

create table if not exists public.quiz_options (
  id           uuid primary key default gen_random_uuid(),
  question_id  uuid not null references public.quiz_questions (id) on delete cascade,
  position     int  not null check (position >= 0),
  text         text not null,
  is_correct   boolean not null default false,
  constraint quiz_options_position_key unique (question_id, position)
);
comment on table public.quiz_options is 'Multiple-choice options. is_correct is readable by staff only; customers receive options without it.';
create index if not exists quiz_options_question_idx on public.quiz_options (question_id);

-- -----------------------------------------------------------------------------
-- game_sessions — GameSession: one participation with a unique transaction ID.
-- UNIQUE(member_id, idempotency_key) is the anti-duplicate-participation guarantee.
-- -----------------------------------------------------------------------------
create table if not exists public.game_sessions (
  id                    uuid primary key default gen_random_uuid(),
  ref                   text not null default public.gen_public_ref('GS'),  -- participation transaction ID
  member_id             uuid not null references public.members (id) on delete cascade,
  game_id               uuid not null references public.games (id) on delete restrict,
  campaign_id           uuid references public.campaigns (id) on delete set null,
  game_type             text not null references public.game_types (key),
  status                public.session_status not null default 'in_progress',
  payment_source        public.payment_source not null,
  pp_cost               int  not null default 0 check (pp_cost >= 0),
  outcome_id            uuid references public.game_outcomes (id) on delete set null,
  outcome               jsonb not null default '{}',        -- snapshot of the result shown to the customer
  draw                  jsonb,                              -- audit of the RNG draw (drawn index, fallback applied)
  question_ids          uuid[],                             -- quiz: questions served, in order
  score                 int,
  correct_count         int,
  question_count        int,
  reward_transaction_id uuid,
  idempotency_key       text not null,
  device_hash           text,
  ip_hash               text,
  started_at            timestamptz not null default now(),
  expires_at            timestamptz,
  completed_at          timestamptz,
  constraint game_sessions_ref_key unique (ref),
  constraint game_sessions_idem_key unique (member_id, idempotency_key)
);
comment on table public.game_sessions is 'GameSession: each participation (unique GS- transaction ID), payment source, server-decided outcome/score, linked reward transaction. Immutable once completed.';
create index if not exists game_sessions_member_game_idx on public.game_sessions (member_id, game_id, started_at desc);
create index if not exists game_sessions_member_idx on public.game_sessions (member_id, started_at desc);
create index if not exists game_sessions_game_idx on public.game_sessions (game_id, started_at);
create index if not exists game_sessions_campaign_idx on public.game_sessions (campaign_id, started_at);
create index if not exists game_sessions_open_idx on public.game_sessions (expires_at) where status = 'in_progress';

-- Quiz answers per session (validated against quiz_options server-side; timing from server clock).
create table if not exists public.game_session_answers (
  session_id   uuid not null references public.game_sessions (id) on delete cascade,
  question_id  uuid not null references public.quiz_questions (id) on delete restrict,
  option_id    uuid references public.quiz_options (id) on delete restrict,
  is_correct   boolean not null default false,
  points       int not null default 0,
  answered_at  timestamptz not null default now(),
  primary key (session_id, question_id)
);
comment on table public.game_session_answers is 'Quiz answers per session with server-side correctness and points.';

-- -----------------------------------------------------------------------------
-- Earned game attempts (from missions, check-in streaks, events, admin grants,
-- bonus-attempt prizes). Free daily attempts are computed from attempt_rules and
-- are not ledgered.
-- -----------------------------------------------------------------------------
create table if not exists public.attempt_balances (
  member_id   uuid not null references public.members (id) on delete cascade,
  game_id     uuid not null references public.games (id) on delete cascade,
  balance     int  not null default 0 check (balance >= 0),
  updated_at  timestamptz not null default now(),
  primary key (member_id, game_id)
);
comment on table public.attempt_balances is 'Earned (non-free) attempts available per member per game. Locked FOR UPDATE when consumed.';

create table if not exists public.attempt_ledger (
  id               uuid primary key default gen_random_uuid(),
  member_id        uuid not null references public.members (id) on delete cascade,
  game_id          uuid not null references public.games (id) on delete cascade,
  delta            int  not null check (delta <> 0),
  balance_after    int  not null check (balance_after >= 0),
  reason           public.attempt_reason not null,
  ref_type         text,
  ref_id           text,
  expires_at       timestamptz,
  idempotency_key  text not null,
  created_by       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  constraint attempt_ledger_idem_key unique (member_id, idempotency_key)
);
comment on table public.attempt_ledger is 'Append-only ledger of earned/consumed game attempts.';
create index if not exists attempt_ledger_member_idx on public.attempt_ledger (member_id, created_at desc);

drop trigger if exists attempt_ledger_append_only on public.attempt_ledger;
create trigger attempt_ledger_append_only before update or delete on public.attempt_ledger
  for each row execute function public.forbid_mutation();

-- -----------------------------------------------------------------------------
-- Probability integrity: an ACTIVE weighted game must have outcomes totalling
-- exactly 10000 bp. Checked when a game is activated and (deferred, at commit)
-- whenever outcomes of an active game change.
-- -----------------------------------------------------------------------------
create or replace function public.assert_game_weights(p_game_id uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  g record;
  total int;
  n int;
begin
  select ga.status, gt.weighted into g
  from public.games ga join public.game_types gt on gt.key = ga.type
  where ga.id = p_game_id;

  if not found or not g.weighted or g.status not in ('active', 'scheduled') then
    return;
  end if;

  select coalesce(sum(weight_bp), 0), count(*) into total, n
  from public.game_outcomes where game_id = p_game_id;

  if n = 0 then
    raise exception 'Game % cannot be active/scheduled without outcomes', p_game_id using errcode = 'P0001';
  end if;
  if total <> 10000 then
    raise exception 'Outcome weights for game % total % bp (% percent); they must total 10000 bp (100 percent)',
      p_game_id, total, round(total / 100.0, 2) using errcode = 'P0001';
  end if;
end;
$$;

create or replace function public.trg_games_check_weights()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  perform public.assert_game_weights(new.id);
  return new;
end;
$$;

create or replace function public.trg_outcomes_check_weights()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.assert_game_weights(old.game_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.assert_game_weights(new.game_id);
  end if;
  return null;
end;
$$;

drop trigger if exists games_check_weights on public.games;
create trigger games_check_weights after insert or update of status, type on public.games
  for each row execute function public.trg_games_check_weights();

drop trigger if exists game_outcomes_check_weights on public.game_outcomes;
create constraint trigger game_outcomes_check_weights
  after insert or update or delete on public.game_outcomes
  deferrable initially deferred
  for each row execute function public.trg_outcomes_check_weights();


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0006_engagement.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0006 · Engagement: daily check-in, missions, badges, leaderboards, QR codes
-- Reward specs used below are arrays: [{"reward_id":"<uuid>","qty":1}, …]
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Daily check-in programmes
-- -----------------------------------------------------------------------------
create table if not exists public.checkin_programs (
  id                  uuid primary key default gen_random_uuid(),
  campaign_id         uuid references public.campaigns (id) on delete cascade,   -- null = always-on programme
  name                text not null,
  description         text not null default '',
  status              public.lifecycle_status not null default 'draft',
  starts_at           timestamptz,
  ends_at             timestamptz,
  eligibility_rule_id uuid references public.eligibility_rules (id) on delete set null,
  base_rewards        jsonb not null default '[]',      -- given on every check-in
  reset_rule          public.streak_reset_rule not null default 'strict',
  grace_days          int not null default 0 check (grace_days between 0 and 7),
  reset_period        public.reset_period not null default 'none',   -- streak also resets each week/month
  qr_multiplier       numeric(4,2) not null default 1 check (qr_multiplier >= 1),  -- location-verified bonus
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint checkin_programs_dates_chk check (ends_at is null or starts_at is null or ends_at > starts_at),
  constraint checkin_programs_rewards_is_array check (jsonb_typeof(base_rewards) = 'array')
);
comment on table public.checkin_programs is 'Daily check-in programme: base reward, streak reset rules (strict/grace, weekly/monthly reset), QR bonus multiplier.';

create table if not exists public.checkin_streak_rules (
  id            uuid primary key default gen_random_uuid(),
  program_id    uuid not null references public.checkin_programs (id) on delete cascade,
  streak_day    int  not null check (streak_day > 0),            -- reward when streak reaches this day
  repeat_every  int  check (repeat_every is null or repeat_every > 0),  -- e.g. every 7 days after
  rewards       jsonb not null default '[]',
  label         text not null default '',
  constraint checkin_streak_rules_day_key unique (program_id, streak_day),
  constraint checkin_streak_rules_rewards_is_array check (jsonb_typeof(rewards) = 'array')
);
comment on table public.checkin_streak_rules is 'Escalating streak ladder (e.g. day 3 +20 PP, day 7 +100 PP + bonus spin).';

-- CheckInHistory: one row per member per programme per business day (anti-abuse via UNIQUE).
create table if not exists public.checkins (
  id            uuid primary key default gen_random_uuid(),
  member_id     uuid not null references public.members (id) on delete cascade,
  program_id    uuid not null references public.checkin_programs (id) on delete cascade,
  day           date not null,                                  -- business day (SGT)
  streak_after  int  not null check (streak_after > 0),
  source        public.checkin_source not null default 'app',
  qr_code_id    uuid,
  device_hash   text,
  created_at    timestamptz not null default now(),
  constraint checkins_once_per_day unique (member_id, program_id, day)
);
comment on table public.checkins is 'Check-in history. UNIQUE(member, programme, day) prevents repeated check-in abuse.';
create index if not exists checkins_member_idx on public.checkins (member_id, day desc);
create index if not exists checkins_day_idx on public.checkins (day);

create table if not exists public.member_streaks (
  member_id    uuid not null references public.members (id) on delete cascade,
  program_id   uuid not null references public.checkin_programs (id) on delete cascade,
  current      int  not null default 0 check (current >= 0),
  best         int  not null default 0 check (best >= 0),
  last_day     date,
  updated_at   timestamptz not null default now(),
  primary key (member_id, program_id)
);
comment on table public.member_streaks is 'Current and best streak per member per check-in programme.';

-- -----------------------------------------------------------------------------
-- Missions & challenges
-- objective: {"type":"spend_amount","target":5000,"filters":{"merchant_ids":["…"],"participating_only":true}}
--   (spend targets in cents; visit/store/check-in/game targets are counts)
-- -----------------------------------------------------------------------------
create table if not exists public.missions (
  id                  uuid primary key default gen_random_uuid(),
  campaign_id         uuid references public.campaigns (id) on delete cascade,
  key                 text not null,
  title               text not null,
  description         text not null default '',
  how_to              text not null default '',
  category            text not null default 'general',   -- shopping | visit | engagement | games | dining …
  icon                text,
  banner_path         text,
  objective_type      public.mission_objective not null,
  objective           jsonb not null default '{}',
  target              numeric(14,2) not null check (target > 0),
  recurrence          public.recurrence not null default 'once',
  enrolment_mode      public.enrolment_mode not null default 'auto',
  max_participants    int check (max_participants is null or max_participants > 0),
  completions_count   int not null default 0,
  rewards             jsonb not null default '[]',
  eligibility_rule_id uuid references public.eligibility_rules (id) on delete set null,
  status              public.lifecycle_status not null default 'draft',
  priority            int not null default 100,
  starts_at           timestamptz,
  ends_at             timestamptz,
  created_by          uuid references auth.users (id) on delete set null,
  updated_by          uuid references auth.users (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint missions_key_key unique (key),
  constraint missions_dates_chk check (ends_at is null or starts_at is null or ends_at > starts_at),
  constraint missions_rewards_is_array check (jsonb_typeof(rewards) = 'array')
);
comment on table public.missions is 'Missions/challenges: objective type + target, recurrence (once/daily/weekly/monthly), enrolment mode, limits, eligibility and rewards.';
create index if not exists missions_live_idx on public.missions (status, objective_type, starts_at, ends_at);
create index if not exists missions_campaign_idx on public.missions (campaign_id);

-- MissionParticipation (opt-in missions; auto missions create a row on first progress).
create table if not exists public.mission_enrolments (
  mission_id   uuid not null references public.missions (id) on delete cascade,
  member_id    uuid not null references public.members (id) on delete cascade,
  enrolled_at  timestamptz not null default now(),
  primary key (mission_id, member_id)
);
comment on table public.mission_enrolments is 'Members participating in a mission (explicit opt-in or implicit on first progress).';
create index if not exists mission_enrolments_member_idx on public.mission_enrolments (member_id);

-- MissionProgress per recurrence period. UNIQUE prevents duplicate completion in a period.
create table if not exists public.mission_progress (
  id                uuid primary key default gen_random_uuid(),
  mission_id        uuid not null references public.missions (id) on delete cascade,
  member_id         uuid not null references public.members (id) on delete cascade,
  period_key        text not null,                       -- 'all' | '2026-11-27' | '2026-W48' | '2026-11'
  progress          numeric(14,2) not null default 0 check (progress >= 0),
  target            numeric(14,2) not null,
  distinct_values   text[] not null default '{}',        -- distinct_stores: merchant ids counted
  completed_at      timestamptz,
  rewarded_at       timestamptz,
  updated_at        timestamptz not null default now(),
  constraint mission_progress_period_key unique (mission_id, member_id, period_key)
);
comment on table public.mission_progress is 'Progress per member per mission per period. One completion per period (UNIQUE).';
create index if not exists mission_progress_member_idx on public.mission_progress (member_id, updated_at desc);
create index if not exists mission_progress_completed_idx on public.mission_progress (mission_id, completed_at) where completed_at is not null;

-- Each source event counts at most once per mission (prevents double counting on retries).
create table if not exists public.mission_progress_events (
  mission_id       uuid not null references public.missions (id) on delete cascade,
  source_event_id  text not null,
  member_id        uuid not null references public.members (id) on delete cascade,
  period_key       text not null,
  amount           numeric(14,2) not null default 1,
  created_at       timestamptz not null default now(),
  primary key (mission_id, source_event_id)
);
comment on table public.mission_progress_events is 'Dedup of events applied to mission progress (idempotent progress updates).';

-- -----------------------------------------------------------------------------
-- Badges & achievements
-- criteria: {"metric":"checkin_streak","op":"gte","value":30}
--   metrics: checkins_total, checkin_streak, missions_completed, games_played, quiz_wins,
--            distinct_stores, visits_count, lifetime_spend_cents, monthly_rank, pp_lifetime_earned
-- -----------------------------------------------------------------------------
create table if not exists public.badges (
  id           uuid primary key default gen_random_uuid(),
  key          text not null,
  name         text not null,
  description  text not null default '',
  image_path   text,
  icon         text,
  tier         public.badge_tier not null default 'bronze',
  hidden       boolean not null default false,          -- secret achievement until earned
  criteria     jsonb not null default '{}',
  rewards      jsonb not null default '[]',
  sort         int not null default 100,
  status       public.record_status not null default 'active',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint badges_key_key unique (key),
  constraint badges_rewards_is_array check (jsonb_typeof(rewards) = 'array')
);
comment on table public.badges is 'Badge definitions with declarative award criteria and optional rewards.';

create table if not exists public.member_badges (
  member_id     uuid not null references public.members (id) on delete cascade,
  badge_id      uuid not null references public.badges (id) on delete cascade,
  awarded_at    timestamptz not null default now(),
  source_event  text,
  primary key (member_id, badge_id)
);
comment on table public.member_badges is 'CustomerBadge: badges earned (each at most once).';
create index if not exists member_badges_awarded_idx on public.member_badges (member_id, awarded_at desc);

-- -----------------------------------------------------------------------------
-- Leaderboards
-- -----------------------------------------------------------------------------
create table if not exists public.leaderboards (
  id            uuid primary key default gen_random_uuid(),
  campaign_id   uuid references public.campaigns (id) on delete cascade,   -- null = global
  key           text not null,
  name          text not null,
  description   text not null default '',
  metric        public.leaderboard_metric not null,
  periods       public.leaderboard_period[] not null default '{daily,weekly,monthly,overall}',
  game_id       uuid references public.games (id) on delete cascade,      -- optional: quiz_score for one quiz
  segment_id    uuid references public.segments (id) on delete set null,
  display_mode  public.display_mode not null default 'masked',
  top_n         int not null default 100 check (top_n between 3 and 1000),
  prize_rules   jsonb not null default '[]',   -- [{"period":"monthly","rank_from":1,"rank_to":3,"rewards":[…]}]
  status        public.lifecycle_status not null default 'draft',
  starts_at     timestamptz,
  ends_at       timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint leaderboards_key_key unique (key)
);
comment on table public.leaderboards is 'Leaderboard definitions: metric, periods (daily/weekly/monthly/overall), scope, privacy display mode, period prizes.';

-- Scores per period, upserted in the same transaction as the scoring event.
create table if not exists public.leaderboard_scores (
  board_id     uuid not null references public.leaderboards (id) on delete cascade,
  period_key   text not null,
  member_id    uuid not null references public.members (id) on delete cascade,
  score        bigint not null default 0,
  reached_at   timestamptz not null default now(),    -- tie-break: earlier wins
  primary key (board_id, period_key, member_id)
);
comment on table public.leaderboard_scores is 'Incremental scores per board per period key. Ranked by score desc, reached_at asc (index-backed).';
create index if not exists leaderboard_scores_rank_idx on public.leaderboard_scores (board_id, period_key, score desc, reached_at asc);
create index if not exists leaderboard_scores_member_idx on public.leaderboard_scores (member_id);

create table if not exists public.leaderboard_snapshots (
  id          uuid primary key default gen_random_uuid(),
  board_id    uuid not null references public.leaderboards (id) on delete cascade,
  period_key  text not null,
  frozen_at   timestamptz not null default now(),
  entries     jsonb not null default '[]',
  prizes_awarded_at timestamptz,
  constraint leaderboard_snapshots_period_key unique (board_id, period_key)
);
comment on table public.leaderboard_snapshots is 'Frozen final rankings per closed period (history + prize awarding).';

create table if not exists public.leaderboard_exclusions (
  board_id    uuid not null references public.leaderboards (id) on delete cascade,
  member_id   uuid not null references public.members (id) on delete cascade,
  reason      text not null default '',
  created_by  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  primary key (board_id, member_id)
);
comment on table public.leaderboard_exclusions is 'Members hidden from a leaderboard by admins (fraud, complaints).';

-- -----------------------------------------------------------------------------
-- QR codes (location-verified check-in, mall visits, event check-ins)
-- -----------------------------------------------------------------------------
create table if not exists public.qr_codes (
  id                     uuid primary key default gen_random_uuid(),
  token                  text not null default encode(extensions.gen_random_bytes(18), 'hex'),
  purpose                public.qr_purpose not null,
  label                  text not null,
  location               text not null default '',
  campaign_id            uuid references public.campaigns (id) on delete cascade,
  mission_id             uuid references public.missions (id) on delete cascade,
  program_id             uuid references public.checkin_programs (id) on delete cascade,
  valid_from             timestamptz,
  valid_to               timestamptz,
  max_scans              int check (max_scans is null or max_scans > 0),
  per_member_daily_limit int not null default 1 check (per_member_daily_limit > 0),
  scans_count            int not null default 0,
  status                 public.record_status not null default 'active',
  created_by             uuid references auth.users (id) on delete set null,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint qr_codes_token_key unique (token)
);
comment on table public.qr_codes is 'Printed/displayed QR codes for location-verified check-ins, visits and events. Token is unguessable (144-bit).';

create table if not exists public.qr_scans (
  id           uuid primary key default gen_random_uuid(),
  qr_code_id   uuid not null references public.qr_codes (id) on delete cascade,
  member_id    uuid not null references public.members (id) on delete cascade,
  day          date not null,
  device_hash  text,
  scanned_at   timestamptz not null default now()
);
comment on table public.qr_scans is 'QR scan log (per-member daily limits, fraud burst detection).';
create index if not exists qr_scans_member_day_idx on public.qr_scans (member_id, qr_code_id, day);
create index if not exists qr_scans_code_idx on public.qr_scans (qr_code_id, scanned_at);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0007_ledgers_transactions.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0007 · Play Points ledger, reward transactions, outbox
-- =============================================================================

-- -----------------------------------------------------------------------------
-- points_ledger — append-only ledger of PLAY POINTS (gamification currency).
-- Completely separate from Suntec+/Capillary loyalty points, which are never
-- stored on this platform. member_profiles.pp_balance is the locked running total.
-- -----------------------------------------------------------------------------
create table if not exists public.points_ledger (
  id               uuid primary key default gen_random_uuid(),
  member_id        uuid not null references public.members (id) on delete cascade,
  delta            int  not null check (delta <> 0),
  balance_after    bigint not null check (balance_after >= 0),
  reason           public.points_reason not null,
  ref_type         text,                  -- game_session | checkin | mission_progress | reward_transaction | admin …
  ref_id           text,
  expires_at       timestamptz,           -- for earned points when PP expiry is enabled
  idempotency_key  text not null,
  note             text,
  created_by       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  constraint points_ledger_idem_key unique (member_id, idempotency_key)
);
comment on table public.points_ledger is 'Append-only Play Points ledger (earn/spend/expire/reverse). Separate from Capillary loyalty points.';
create index if not exists points_ledger_member_idx on public.points_ledger (member_id, created_at desc);
create index if not exists points_ledger_reason_idx on public.points_ledger (reason, created_at);

drop trigger if exists points_ledger_append_only on public.points_ledger;
create trigger points_ledger_append_only before update or delete on public.points_ledger
  for each row execute function public.forbid_mutation();

-- -----------------------------------------------------------------------------
-- reward_transactions — RewardTransaction: every allocation of a reward to a member,
-- from any source, with delivery status towards Capillary / VMS and redemption tracking.
-- UNIQUE(source, source_id, reward_id) makes allocation idempotent per triggering record.
-- -----------------------------------------------------------------------------
create table if not exists public.reward_transactions (
  id               uuid primary key default gen_random_uuid(),
  ref              text not null default public.gen_public_ref('RT'),
  member_id        uuid not null references public.members (id) on delete cascade,
  reward_id        uuid not null references public.rewards (id) on delete restrict,
  reward_type      public.reward_type not null,
  reward_snapshot  jsonb not null default '{}',     -- name/value/cost at allocation time
  quantity         int  not null default 1 check (quantity > 0),
  source           public.reward_source not null,
  source_id        text not null,                   -- game_session id, mission_progress id, checkin id, admin request id …
  campaign_id      uuid references public.campaigns (id) on delete set null,
  pp_cost          int  not null default 0 check (pp_cost >= 0),   -- PP spent (catalogue redemption)
  unit_cost_cents  int  not null default 0,
  status           public.reward_txn_status not null default 'pending',
  external_ref     text,                            -- Capillary txn id / VMS voucher id
  voucher_code     text,                            -- visible to the owning member only (RLS)
  claim_token      text,                            -- QR claim code for gifts / privileges
  attempts         int  not null default 0,
  last_error       text,
  issued_at        timestamptz,
  redeemed_at      timestamptz,
  expires_at       timestamptz,
  cancelled_at     timestamptz,
  cancel_reason    text,
  idempotency_key  text,
  created_by       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint reward_transactions_ref_key unique (ref),
  constraint reward_transactions_source_key unique (source, source_id, reward_id),
  constraint reward_transactions_idem_key unique (member_id, idempotency_key)
);
comment on table public.reward_transactions is 'RewardTransaction: allocation lifecycle pending→issued→redeemed/expired (or failed→retry/cancel), external refs from Capillary/VMS.';
create index if not exists reward_transactions_member_idx on public.reward_transactions (member_id, created_at desc);
create index if not exists reward_transactions_status_idx on public.reward_transactions (status, updated_at);
create index if not exists reward_transactions_reward_idx on public.reward_transactions (reward_id, created_at);
create index if not exists reward_transactions_campaign_idx on public.reward_transactions (campaign_id, created_at);
create index if not exists reward_transactions_expiry_idx on public.reward_transactions (expires_at) where status = 'issued';

-- game_sessions → reward_transactions (added here because of creation order)
do $$ begin
  alter table public.game_sessions
    add constraint game_sessions_reward_txn_fk foreign key (reward_transaction_id)
    references public.reward_transactions (id) on delete set null;
exception when duplicate_object then null; end $$;

-- voucher_code_pool → reward_transactions
do $$ begin
  alter table public.voucher_code_pool
    add constraint voucher_code_pool_txn_fk foreign key (assigned_txn_id)
    references public.reward_transactions (id) on delete set null;
exception when duplicate_object then null; end $$;

-- -----------------------------------------------------------------------------
-- outbox — transactional outbox for all external side effects (Capillary points,
-- VMS vouchers, push notifications). Written in the same DB transaction as the
-- business change; delivered asynchronously with retries & exponential backoff.
-- kind: capillary.award_points | capillary.deduct_points | vms.issue_voucher | push.send …
-- -----------------------------------------------------------------------------
create table if not exists public.outbox (
  id               uuid primary key default gen_random_uuid(),
  kind             text not null,
  aggregate_type   text not null,                 -- reward_transaction | notification …
  aggregate_id     uuid not null,
  payload          jsonb not null default '{}',
  status           public.outbox_status not null default 'pending',
  attempts         int  not null default 0,
  max_attempts     int  not null default 10,
  next_attempt_at  timestamptz not null default now(),
  locked_until     timestamptz,
  last_error       text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint outbox_aggregate_kind_key unique (aggregate_type, aggregate_id, kind)
);
comment on table public.outbox is 'Transactional outbox for external calls (Capillary, VMS, push). Idempotency key towards upstream = aggregate_id.';
create index if not exists outbox_due_idx on public.outbox (next_attempt_at) where status in ('pending', 'retry');
create index if not exists outbox_status_idx on public.outbox (status, updated_at);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0008_notifications.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0008 · Notifications: templates (admin-configurable), inbox, dispatches
-- =============================================================================

-- Template per event key. Variables use {{mustache}} syntax, rendered server-side.
-- Event keys: campaign_launched, mission_available, checkin_reminder, mission_completed,
-- game_result, reward_allocated, reward_expiring, badge_unlocked, leaderboard_update
create table if not exists public.notification_templates (
  id                 uuid primary key default gen_random_uuid(),
  key                text not null,
  name               text not null,
  channels           public.notification_channel[] not null default '{inbox}',
  title              text not null,
  body               text not null,
  deep_link          text,
  quiet_hours_start  time,                 -- push suppressed inside quiet hours (business timezone)
  quiet_hours_end    time,
  locale             text not null default 'en',
  status             public.record_status not null default 'active',
  updated_by         uuid references auth.users (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint notification_templates_key_locale_key unique (key, locale)
);
comment on table public.notification_templates is 'Admin-configurable notification templates per event (channels, title/body with {{variables}}, deep link, quiet hours).';

-- In-app inbox (always written). Realtime-enabled so the UI updates near-real-time.
create table if not exists public.notifications (
  id            uuid primary key default gen_random_uuid(),
  member_id     uuid not null references public.members (id) on delete cascade,
  template_key  text not null,
  title         text not null,
  body          text not null,
  deep_link     text,
  data          jsonb not null default '{}',
  dedupe_key    text,                                 -- prevents duplicate notifications for one event
  read_at       timestamptz,
  expires_at    timestamptz,
  created_at    timestamptz not null default now(),
  constraint notifications_dedupe_key unique (member_id, dedupe_key)
);
comment on table public.notifications is 'Customer in-app inbox. Push/email delivery is tracked in notification_dispatches.';
create index if not exists notifications_member_idx on public.notifications (member_id, created_at desc);
create index if not exists notifications_unread_idx on public.notifications (member_id) where read_at is null;

create table if not exists public.notification_dispatches (
  id               uuid primary key default gen_random_uuid(),
  notification_id  uuid not null references public.notifications (id) on delete cascade,
  channel          public.notification_channel not null,
  status           public.dispatch_status not null default 'pending',
  external_ref     text,
  last_error       text,
  sent_at          timestamptz,
  created_at       timestamptz not null default now(),
  constraint notification_dispatches_channel_key unique (notification_id, channel)
);
comment on table public.notification_dispatches is 'Per-channel delivery status (push via existing Suntec+ push service, email).';
create index if not exists notification_dispatches_status_idx on public.notification_dispatches (status, created_at);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0009_platform.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0009 · Platform: API clients, session handoff, idempotency, rate limits,
--        inbound/domain events, fraud signals, audit log, analytics rollups
-- These tables are SERVER-ONLY (service role) unless a staff policy says otherwise.
-- =============================================================================

-- Integration clients (Suntec+ backend, Capillary webhooks, POS). Key stored as SHA-256 only.
create table if not exists public.api_clients (
  id                 uuid primary key default gen_random_uuid(),
  name               text not null,
  key_prefix         text not null,                        -- first chars shown in admin, e.g. "sk_live_ab12"
  key_hash           text not null,                        -- sha256(api key)
  scopes             text[] not null default '{}',         -- sessions:write events:write members:read attempts:write webhooks:write
  require_signature  boolean not null default false,       -- require X-Signature HMAC on requests
  rate_limit_per_min int not null default 1200 check (rate_limit_per_min > 0),
  active             boolean not null default true,
  expires_at         timestamptz,
  last_used_at       timestamptz,
  created_by         uuid references auth.users (id) on delete set null,
  revoked_at         timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint api_clients_key_hash_key unique (key_hash)
);
comment on table public.api_clients is 'Server-to-server API clients with hashed keys, scopes, optional HMAC signing and per-client rate limits.';

-- Single-use, short-lived code that the Suntec+ backend exchanges for an in-app session (SSO handoff).
create table if not exists public.session_handoffs (
  id           uuid primary key default gen_random_uuid(),
  code_hash    text not null,
  member_id    uuid not null references public.members (id) on delete cascade,
  client_id    uuid references public.api_clients (id) on delete set null,
  entry        text,                         -- deep-link target inside the module (spin, missions…)
  return_url   text,
  expires_at   timestamptz not null,
  used_at      timestamptz,
  ip_hash      text,
  created_at   timestamptz not null default now(),
  constraint session_handoffs_code_hash_key unique (code_hash)
);
comment on table public.session_handoffs is 'SSO handoff codes (hash only, 60 s TTL, single use) for opening the module inside the Suntec+ app WebView.';
create index if not exists session_handoffs_expiry_idx on public.session_handoffs (expires_at) where used_at is null;

-- Idempotency store for value-moving API calls. Replays return the stored response.
create table if not exists public.idempotency_keys (
  scope            text not null,            -- e.g. member:<uuid>:POST /games/:id/sessions | client:<uuid>
  key              text not null,
  request_hash     text not null,            -- sha256 of method+path+body; mismatch → 409
  state            public.idempotency_state not null default 'in_progress',
  response_status  int,
  response         jsonb,
  created_at       timestamptz not null default now(),
  expires_at       timestamptz not null default now() + interval '24 hours',
  primary key (scope, key)
);
comment on table public.idempotency_keys is 'Idempotency-Key records (24 h): duplicate requests replay the original response.';
create index if not exists idempotency_keys_expiry_idx on public.idempotency_keys (expires_at);

-- Fixed-window rate limit counters. UNLOGGED: fast, and losing them on crash is acceptable.
create unlogged table if not exists public.rate_limits (
  key           text not null,                 -- member:<id>:play | ip:<hash> | client:<id>
  window_start  timestamptz not null,
  count         int not null default 0,
  primary key (key, window_start)
);
comment on table public.rate_limits is 'Fixed-window rate-limit counters (unlogged, purged continuously).';

-- Inbound integration events (transactions, visits, voucher redemptions…). Dedup per source.
create table if not exists public.inbound_events (
  id            uuid primary key default gen_random_uuid(),
  source        text not null,                 -- api client name or webhook:<provider>
  client_id     uuid references public.api_clients (id) on delete set null,
  type          text not null,                 -- transaction | mall_visit | voucher_redeemed | campaign_participation | activity
  external_id   text not null,
  member_id     uuid references public.members (id) on delete set null,
  suntec_member_id text,
  occurred_at   timestamptz not null,
  payload       jsonb not null default '{}',
  status        public.inbound_event_status not null default 'received',
  effects       jsonb not null default '[]',
  error         text,
  received_at   timestamptz not null default now(),
  processed_at  timestamptz,
  constraint inbound_events_dedupe_key unique (source, external_id)
);
comment on table public.inbound_events is 'Events received from Suntec+/Capillary/POS, deduplicated by (source, external_id), with resulting effects.';
create index if not exists inbound_events_member_idx on public.inbound_events (member_id, occurred_at desc);
create index if not exists inbound_events_status_idx on public.inbound_events (status, received_at);

-- Internal domain events emitted inside engine transactions; consumed for badge
-- evaluation, notifications and analytics.
create table if not exists public.domain_events (
  id            bigint generated always as identity primary key,
  type          text not null,                 -- checkin.completed | game.completed | mission.completed | reward.allocated …
  member_id     uuid references public.members (id) on delete set null,
  payload       jsonb not null default '{}',
  created_at    timestamptz not null default now(),
  processed_at  timestamptz
);
comment on table public.domain_events is 'Domain events written in the same transaction as engine changes (event bus between modules).';
create index if not exists domain_events_unprocessed_idx on public.domain_events (id) where processed_at is null;
create index if not exists domain_events_member_idx on public.domain_events (member_id, created_at desc);
create index if not exists domain_events_type_idx on public.domain_events (type, created_at);

-- Fraud signals (velocity, device sharing, QR bursts, quiz timing anomalies…).
create table if not exists public.fraud_signals (
  id            uuid primary key default gen_random_uuid(),
  member_id     uuid references public.members (id) on delete cascade,
  kind          text not null,                 -- velocity | device_sharing | qr_burst | quiz_timing | duplicate_attempt …
  severity      public.fraud_severity not null default 'low',
  details       jsonb not null default '{}',
  device_hash   text,
  ip_hash       text,
  resolved_at   timestamptz,
  resolved_by   uuid references auth.users (id) on delete set null,
  resolution    text,
  created_at    timestamptz not null default now()
);
comment on table public.fraud_signals is 'Anti-fraud signals for review; high severity may auto-flag the member.';
create index if not exists fraud_signals_member_idx on public.fraud_signals (member_id, created_at desc);
create index if not exists fraud_signals_open_idx on public.fraud_signals (severity, created_at) where resolved_at is null;

-- -----------------------------------------------------------------------------
-- audit_log — append-only record of every administrative change.
-- Written automatically by trigger on configuration tables (actor = auth.uid()
-- or the app.actor_id setting when the API acts via the service role).
-- -----------------------------------------------------------------------------
create table if not exists public.audit_log (
  id           bigint generated always as identity primary key,
  actor_type   public.actor_type not null,
  actor_id     uuid,
  actor_label  text,
  action       text not null,                  -- <table>.insert|update|delete or domain action e.g. reward.grant
  entity       text not null,
  entity_id    text,
  before       jsonb,
  after        jsonb,
  reason       text,
  ip_hash      text,
  request_id   text,
  created_at   timestamptz not null default now()
);
comment on table public.audit_log is 'Append-only audit trail of admin actions and manual operations (who, what, before/after, when).';
create index if not exists audit_log_entity_idx on public.audit_log (entity, entity_id, created_at desc);
create index if not exists audit_log_actor_idx on public.audit_log (actor_id, created_at desc);
create index if not exists audit_log_created_idx on public.audit_log (created_at desc);

drop trigger if exists audit_log_append_only on public.audit_log;
create trigger audit_log_append_only before update or delete on public.audit_log
  for each row execute function public.forbid_mutation();

-- Generic row-change audit trigger.
-- Optional trigger argument 'staff_only': only log changes made by a staff user
-- (used on tables the engine also updates at high frequency, e.g. inventory counters).
create or replace function public.audit_row_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_actor_type public.actor_type;
  v_setting text;
  v_before jsonb;
  v_after jsonb;
  v_id text;
begin
  if v_actor is null then
    v_setting := nullif(current_setting('app.actor_id', true), '');
    if v_setting is not null then v_actor := v_setting::uuid; end if;
  end if;

  if v_actor is null then
    v_actor_type := 'system';
  elsif exists (select 1 from public.staff_users s where s.id = v_actor) then
    v_actor_type := 'staff';
  else
    v_actor_type := 'member';
  end if;

  if tg_nargs > 0 and tg_argv[0] = 'staff_only' and v_actor_type <> 'staff' then
    return coalesce(new, old);
  end if;

  if tg_op <> 'INSERT' then v_before := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_after := to_jsonb(new); end if;

  -- skip no-op updates (only updated_at changed)
  if tg_op = 'UPDATE' and (v_before - 'updated_at') = (v_after - 'updated_at') then
    return new;
  end if;

  v_id := coalesce(v_after ->> 'id', v_before ->> 'id', v_after ->> 'key', v_before ->> 'key',
                   v_after ->> 'reward_id', v_before ->> 'reward_id');

  insert into public.audit_log (actor_type, actor_id, action, entity, entity_id, before, after, request_id)
  values (v_actor_type, v_actor, tg_table_name || '.' || lower(tg_op), tg_table_name, v_id,
          v_before, v_after, nullif(current_setting('app.request_id', true), ''));

  return coalesce(new, old);
end;
$$;

-- -----------------------------------------------------------------------------
-- analytics_daily — pre-aggregated daily metrics for dashboards & reports.
-- Dimension columns use a zero UUID for "all" so they can be part of the PK.
-- -----------------------------------------------------------------------------
create table if not exists public.analytics_daily (
  day          date not null,
  metric       text not null,                 -- dau | plays | wins | pp_issued | rewards_issued | rewards_redeemed | missions_completed | checkins …
  campaign_id  uuid not null default '00000000-0000-0000-0000-000000000000',
  game_id      uuid not null default '00000000-0000-0000-0000-000000000000',
  value        numeric(18,2) not null default 0,
  computed_at  timestamptz not null default now(),
  primary key (day, metric, campaign_id, game_id)
);
comment on table public.analytics_daily is 'Daily KPI rollups (refreshed by scheduled job) for dashboards, reports and BI.';
create index if not exists analytics_daily_metric_idx on public.analytics_daily (metric, day);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0010_mock_capillary.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0010 · MOCK Capillary loyalty & voucher system (DEV / SIT only)
--
-- Simulates the EXISTING Suntec+ loyalty platform (Capillary) and Voucher
-- Management System so the full flow can be developed and tested before API
-- access is granted. The gamification engine NEVER reads these tables directly —
-- it goes through the LoyaltyAdapter / VoucherAdapter (packages/core), whose
-- "mock" implementation calls server-only functions added in Phase 2.
--
-- Do NOT deploy to PROD (set LOYALTY_ADAPTER=capillary there).
-- =============================================================================

create schema if not exists mock_capillary;
comment on schema mock_capillary is 'Mock of the external Capillary loyalty platform + voucher system. Not used in production.';

create table if not exists mock_capillary.members (
  member_id    text primary key,              -- e.g. SUN-00012345
  card_no      text not null unique,
  first_name   text not null,
  last_name    text not null,
  email        extensions.citext unique,
  mobile       text,
  tier         text not null default 'member',  -- member | silver | gold | platinum
  tags         text[] not null default '{}',
  dob          date,
  joined_at    timestamptz not null default now(),
  status       text not null default 'active' check (status in ('active', 'suspended', 'closed'))
);
comment on table mock_capillary.members is 'Mock Capillary member master.';

create table if not exists mock_capillary.points_accounts (
  member_id    text primary key references mock_capillary.members (member_id) on delete cascade,
  balance      bigint not null default 0 check (balance >= 0),
  updated_at   timestamptz not null default now()
);
comment on table mock_capillary.points_accounts is 'Mock Suntec+ loyalty points balance (the real one lives in Capillary).';

create table if not exists mock_capillary.points_transactions (
  id               uuid primary key default gen_random_uuid(),
  external_ref     text not null unique default ('CAP-TX-' || upper(substr(encode(extensions.gen_random_bytes(6), 'hex'), 1, 10))),
  member_id        text not null references mock_capillary.members (member_id) on delete cascade,
  delta            bigint not null check (delta <> 0),
  reason           text not null,
  idempotency_key  text not null unique,     -- Capillary-style dedupe: same key → same transaction
  reversed_by      uuid,
  created_at       timestamptz not null default now()
);
comment on table mock_capillary.points_transactions is 'Mock loyalty points transactions with idempotency.';
create index if not exists mock_points_tx_member_idx on mock_capillary.points_transactions (member_id, created_at desc);

create table if not exists mock_capillary.coupon_series (
  series_id         text primary key,          -- e.g. DIN5
  name              text not null,
  face_value_cents  int  not null default 0,
  validity_days     int  not null default 30,
  merchant_code     text,
  active            boolean not null default true
);
comment on table mock_capillary.coupon_series is 'Mock voucher/coupon series in the Voucher Management System.';

create table if not exists mock_capillary.coupons (
  id               uuid primary key default gen_random_uuid(),
  external_ref     text not null unique default ('VMS-' || upper(substr(encode(extensions.gen_random_bytes(6), 'hex'), 1, 10))),
  series_id        text not null references mock_capillary.coupon_series (series_id),
  member_id        text not null references mock_capillary.members (member_id) on delete cascade,
  code             text not null unique,
  status           text not null default 'issued' check (status in ('issued', 'redeemed', 'expired', 'cancelled')),
  idempotency_key  text not null unique,
  issued_at        timestamptz not null default now(),
  redeemed_at      timestamptz,
  expires_at       timestamptz
);
comment on table mock_capillary.coupons is 'Mock vouchers issued to members.';
create index if not exists mock_coupons_member_idx on mock_capillary.coupons (member_id, issued_at desc);

-- Lock the mock schema down: no access for API roles except the service role.
do $$ begin
  revoke all on schema mock_capillary from public;
  revoke all on all tables in schema mock_capillary from anon, authenticated;
  grant usage on schema mock_capillary to service_role;
  grant all on all tables in schema mock_capillary to service_role;
exception when undefined_object then null; end $$;

alter table mock_capillary.members             enable row level security;
alter table mock_capillary.points_accounts     enable row level security;
alter table mock_capillary.points_transactions enable row level security;
alter table mock_capillary.coupon_series       enable row level security;
alter table mock_capillary.coupons             enable row level security;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0011_triggers.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0011 · Triggers: updated_at maintenance and automatic audit logging
-- =============================================================================

-- updated_at on every table that has the column
do $$
declare
  t text;
begin
  foreach t in array array[
    'app_settings','members','member_profiles','staff_users','segments','eligibility_rules','merchants',
    'campaigns','reward_categories','rewards','reward_inventory','games','game_outcomes','quiz_questions',
    'attempt_balances','checkin_programs','member_streaks','missions','mission_progress','badges',
    'leaderboards','qr_codes','reward_transactions','outbox','notification_templates','api_clients'
  ] loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format('create trigger set_updated_at before update on public.%I
                    for each row execute function public.set_updated_at()', t);
  end loop;
end $$;

-- Audit: every change to configuration / access-control tables
do $$
declare
  t text;
begin
  foreach t in array array[
    'app_settings','staff_users','staff_user_roles','role_permissions','segments','eligibility_rules',
    'merchants','campaigns','campaign_segments','reward_categories','rewards','games','game_outcomes',
    'quiz_questions','quiz_options','checkin_programs','checkin_streak_rules','badges','leaderboards',
    'leaderboard_exclusions','notification_templates','api_clients'
  ] loop
    execute format('drop trigger if exists audit_row_change on public.%I', t);
    execute format('create trigger audit_row_change after insert or update or delete on public.%I
                    for each row execute function public.audit_row_change()', t);
  end loop;

  -- Tables the engine also updates at high frequency: audit staff changes only.
  foreach t in array array['reward_inventory','missions','qr_codes'] loop
    execute format('drop trigger if exists audit_row_change on public.%I', t);
    execute format('create trigger audit_row_change after insert or update or delete on public.%I
                    for each row execute function public.audit_row_change(%L)', t, 'staff_only');
  end loop;
end $$;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0012_rls_policies.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0012 · Row Level Security — enabled on EVERY table
--
-- Model:
--   * Customers (role `authenticated`, linked via members.auth_user_id) can only
--     READ their own rows. They never write directly: every customer action goes
--     through the API → SECURITY DEFINER engine functions (Phase 2).
--   * Staff are checked by permission via has_permission() (RBAC, see 0002).
--   * Platform tables (idempotency, rate limits, handoffs, domain events) have NO
--     policies → reachable only by the service role on the server.
--   * Sensitive config (outcome weights, quiz answers, segments) is staff-only.
-- Policies call helpers through (select …) so Postgres evaluates them once per query.
-- Safe to re-run (drop policy if exists → create policy).
-- =============================================================================

-- 1) Enable RLS on all tables in public -----------------------------------------
do $$
declare r record;
begin
  for r in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', r.tablename);
  end loop;
end $$;

-- Helper used only while this migration runs: (re)create a policy idempotently.
create or replace function public._upsert_policy(
  p_table text, p_name text, p_cmd text, p_using text, p_check text default null
) returns void
language plpgsql
set search_path = ''
as $$
begin
  execute format('drop policy if exists %I on public.%I', p_name, p_table);
  execute format(
    'create policy %I on public.%I as permissive for %s to authenticated %s %s',
    p_name, p_table, p_cmd,
    case when p_using is not null then 'using (' || p_using || ')' else '' end,
    case when p_check is not null then 'with check (' || p_check || ')' else '' end
  );
end;
$$;

-- 2) Customer-owned data: member reads own rows; staff read with a permission ----
do $$
declare
  r record;
begin
  for r in select * from (values
    ('member_profiles',      'customers.read'),
    ('game_sessions',        'customers.read'),
    ('attempt_balances',     'customers.read'),
    ('attempt_ledger',       'customers.read'),
    ('checkins',             'customers.read'),
    ('member_streaks',       'customers.read'),
    ('mission_enrolments',   'customers.read'),
    ('mission_progress',     'customers.read'),
    ('member_badges',        'customers.read'),
    ('points_ledger',        'customers.read'),
    ('reward_transactions',  'rewards.read'),
    ('notifications',        'customers.read'),
    ('leaderboard_scores',   'customers.read'),
    ('qr_scans',             'customers.read')
  ) as t(tbl, perm) loop
    perform public._upsert_policy(r.tbl, 'member_read_own', 'select',
      'member_id = (select public.current_member_id())');
    perform public._upsert_policy(r.tbl, 'staff_read', 'select',
      format('(select public.has_permission(%L))', r.perm));
  end loop;
end $$;

-- reward transactions are also visible to customer-service staff
select public._upsert_policy('reward_transactions', 'staff_read_cs', 'select',
  '(select public.has_permission(''customers.read''))');

-- members: own row; unmasked staff access requires customers.pii
-- (masked search for other roles is provided by an RPC in Phase 3)
select public._upsert_policy('members', 'member_read_own', 'select', 'id = (select public.current_member_id())');
select public._upsert_policy('members', 'staff_read_pii', 'select', '(select public.has_permission(''customers.pii''))');

select public._upsert_policy('member_devices', 'staff_read', 'select', '(select public.has_permission(''customers.read''))');

-- quiz answers: via the parent session
select public._upsert_policy('game_session_answers', 'member_read_own', 'select',
  'exists (select 1 from public.game_sessions s where s.id = session_id and s.member_id = (select public.current_member_id()))');
select public._upsert_policy('game_session_answers', 'staff_read', 'select', '(select public.has_permission(''customers.read''))');

-- notifications: a member may mark their own notifications as read (column-restricted below)
select public._upsert_policy('notifications', 'member_mark_read', 'update',
  'member_id = (select public.current_member_id())', 'member_id = (select public.current_member_id())');
do $$ begin
  revoke update on public.notifications from authenticated;
  grant update (read_at) on public.notifications to authenticated;
exception when undefined_object then null; end $$;

-- 3) Customer-visible configuration (published items only) ----------------------
select public._upsert_policy('campaigns', 'member_read_published', 'select',
  '(select public.current_member_id()) is not null and status in (''active'', ''scheduled'')');
select public._upsert_policy('games', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('missions', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('checkin_programs', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('checkin_streak_rules', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and exists (select 1 from public.checkin_programs p where p.id = program_id and p.status = ''active'')');
select public._upsert_policy('badges', 'member_read_visible', 'select',
  '(select public.current_member_id()) is not null and status = ''active'' and (not hidden or exists (select 1 from public.member_badges mb where mb.badge_id = badges.id and mb.member_id = (select public.current_member_id())))');
select public._upsert_policy('rewards', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('reward_categories', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('merchants', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('leaderboards', 'member_read_active', 'select',
  '(select public.current_member_id()) is not null and status = ''active''');
select public._upsert_policy('game_types', 'authenticated_read', 'select', 'true');
-- NOT customer-visible: game_outcomes (weights), quiz_questions/quiz_options (answers),
-- segments, eligibility_rules, reward_inventory, voucher_code_pool, qr_codes, templates.

-- 4) Staff configuration: read with campaigns.read / rewards.read, write with the module permission
do $$
declare
  r record;
begin
  for r in select * from (values
    -- table,                   read expression,                                                         write expression
    ('campaigns',             'campaigns.read', '(select public.has_permission(''campaigns.write''))'),
    ('campaign_segments',     'campaigns.read', '(select public.has_permission(''campaigns.write''))'),
    ('segments',              'campaigns.read', '(select public.has_permission(''campaigns.write''))'),
    ('eligibility_rules',     'campaigns.read', '(select public.has_permission(''campaigns.write''))'),
    ('games',                 'campaigns.read', '(select public.has_permission(''games.write''))'),
    ('game_outcomes',         'campaigns.read', '(select public.has_permission(''games.write''))'),
    ('quiz_questions',        'campaigns.read', '((select public.has_permission(''games.write'')) or (select public.has_permission(''content.write'')))'),
    ('quiz_options',          'campaigns.read', '((select public.has_permission(''games.write'')) or (select public.has_permission(''content.write'')))'),
    ('missions',              'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('checkin_programs',      'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('checkin_streak_rules',  'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('badges',                'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('leaderboards',          'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('leaderboard_exclusions','campaigns.read', '((select public.has_permission(''missions.write'')) or (select public.has_permission(''customers.act'')))'),
    ('leaderboard_snapshots', 'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('qr_codes',              'campaigns.read', '(select public.has_permission(''missions.write''))'),
    ('merchants',             'campaigns.read', '((select public.has_permission(''rewards.write'')) or (select public.has_permission(''campaigns.write'')))'),
    ('rewards',               'rewards.read',   '(select public.has_permission(''rewards.write''))'),
    ('reward_categories',     'rewards.read',   '(select public.has_permission(''rewards.write''))'),
    ('reward_inventory',      'rewards.read',   '(select public.has_permission(''rewards.write''))'),
    ('reward_inventory_daily','rewards.read',   'false'),
    ('voucher_code_pool',     'rewards.write',  '(select public.has_permission(''rewards.write''))'),
    ('notification_templates','campaigns.read', '(select public.has_permission(''notifications.write''))')
  ) as t(tbl, read_perm, write_expr) loop
    perform public._upsert_policy(r.tbl, 'staff_read', 'select', format('(select public.has_permission(%L))', r.read_perm));
    if r.write_expr <> 'false' then
      perform public._upsert_policy(r.tbl, 'staff_insert', 'insert', null, r.write_expr);
      perform public._upsert_policy(r.tbl, 'staff_update', 'update', r.write_expr, r.write_expr);
      perform public._upsert_policy(r.tbl, 'staff_delete', 'delete', r.write_expr);
    end if;
  end loop;
end $$;

-- 5) Access control, settings, integration & operations ------------------------
select public._upsert_policy('app_settings', 'staff_read', 'select', '(select public.is_staff())');
select public._upsert_policy('app_settings', 'staff_update', 'update',
  '(select public.has_permission(''settings.manage''))', '(select public.has_permission(''settings.manage''))');

select public._upsert_policy('roles', 'staff_read', 'select', '(select public.is_staff())');
select public._upsert_policy('permissions', 'staff_read', 'select', '(select public.is_staff())');
select public._upsert_policy('role_permissions', 'staff_read', 'select', '(select public.is_staff())');
select public._upsert_policy('role_permissions', 'staff_write', 'all',
  '(select public.has_permission(''staff.manage''))', '(select public.has_permission(''staff.manage''))');

select public._upsert_policy('staff_users', 'staff_read_self', 'select', 'id = (select auth.uid())');
select public._upsert_policy('staff_users', 'staff_read_all', 'select', '(select public.has_permission(''staff.manage''))');
select public._upsert_policy('staff_users', 'staff_write', 'all',
  '(select public.has_permission(''staff.manage''))', '(select public.has_permission(''staff.manage''))');
select public._upsert_policy('staff_user_roles', 'staff_read_self', 'select', 'user_id = (select auth.uid())');
select public._upsert_policy('staff_user_roles', 'staff_read_all', 'select', '(select public.has_permission(''staff.manage''))');
select public._upsert_policy('staff_user_roles', 'staff_write', 'all',
  '(select public.has_permission(''staff.manage''))', '(select public.has_permission(''staff.manage''))');

select public._upsert_policy('api_clients', 'staff_manage', 'all',
  '(select public.has_permission(''api_clients.manage''))', '(select public.has_permission(''api_clients.manage''))');

select public._upsert_policy('audit_log', 'staff_read_all', 'select', '(select public.has_permission(''audit.read''))');
select public._upsert_policy('audit_log', 'staff_read_own', 'select',
  'actor_id = (select auth.uid()) and (select public.has_permission(''audit.read_own''))');

select public._upsert_policy('fraud_signals', 'staff_read', 'select', '(select public.has_permission(''customers.read''))');
select public._upsert_policy('fraud_signals', 'staff_resolve', 'update',
  '(select public.has_permission(''customers.act''))', '(select public.has_permission(''customers.act''))');

select public._upsert_policy('outbox', 'staff_read', 'select', '(select public.has_permission(''rewards.read''))');
select public._upsert_policy('inbound_events', 'staff_read', 'select', '(select public.has_permission(''customers.read''))');
select public._upsert_policy('notification_dispatches', 'staff_read', 'select', '(select public.has_permission(''customers.read''))');
select public._upsert_policy('analytics_daily', 'staff_read', 'select', '(select public.has_permission(''reports.read''))');

-- Server-only tables (no policies on purpose): idempotency_keys, rate_limits,
-- session_handoffs, domain_events, mission_progress_events. Belt and braces:
do $$ begin
  revoke all on public.idempotency_keys, public.rate_limits, public.session_handoffs,
                public.domain_events, public.mission_progress_events from anon, authenticated;
exception when undefined_object then null; end $$;

-- Anonymous visitors get nothing from any table.
do $$ begin
  revoke all on all tables in schema public from anon;
exception when undefined_object then null; end $$;

drop function if exists public._upsert_policy(text, text, text, text, text);

-- 6) Publish guard: changing status of campaigns/games/missions needs campaigns.publish
create or replace function public.enforce_publish_permission()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is not null
     and public.is_staff()
     and (tg_op = 'INSERT' and new.status not in ('draft')
          or tg_op = 'UPDATE' and new.status is distinct from old.status)
     and not public.has_permission('campaigns.publish') then
    raise exception 'Permission campaigns.publish is required to change the status of %', tg_table_name
      using errcode = '42501';
  end if;
  return new;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array['campaigns','games','missions','checkin_programs','leaderboards'] loop
    execute format('drop trigger if exists enforce_publish_permission on public.%I', t);
    execute format('create trigger enforce_publish_permission before insert or update of status on public.%I
                    for each row execute function public.enforce_publish_permission()', t);
  end loop;
end $$;

-- 7) Lock down internal functions (Postgres grants EXECUTE to PUBLIC by default) --
do $$ begin
  revoke execute on function public.secure_random_int(int) from public, anon, authenticated;
  revoke execute on function public.assert_game_weights(uuid) from public, anon, authenticated;
  revoke execute on function public.gen_public_ref(text) from anon, authenticated;
exception when undefined_object then null; end $$;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 0013_storage_realtime.sql >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0013 · Storage bucket for banners/badge art/quiz images + Realtime inbox
-- Supabase-specific; each block is skipped gracefully if the feature is absent.
-- =============================================================================

-- Public-read bucket for marketing assets (banners, badge artwork, quiz images, merchant logos).
-- Uploads/changes are restricted to staff with content/campaign permissions.
do $$
begin
  if exists (select 1 from information_schema.schemata where schema_name = 'storage') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('public-assets', 'public-assets', true, 5242880,
            array['image/png', 'image/jpeg', 'image/webp', 'image/svg+xml', 'image/gif'])
    on conflict (id) do update set public = excluded.public,
      file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

    execute 'drop policy if exists "public-assets: staff upload" on storage.objects';
    execute $p$create policy "public-assets: staff upload" on storage.objects for insert to authenticated
      with check (bucket_id = 'public-assets' and ((select public.has_permission('content.write'))
                  or (select public.has_permission('campaigns.write')) or (select public.has_permission('rewards.write'))))$p$;

    execute 'drop policy if exists "public-assets: staff update" on storage.objects';
    execute $p$create policy "public-assets: staff update" on storage.objects for update to authenticated
      using (bucket_id = 'public-assets' and ((select public.has_permission('content.write'))
             or (select public.has_permission('campaigns.write')) or (select public.has_permission('rewards.write'))))$p$;

    execute 'drop policy if exists "public-assets: staff delete" on storage.objects';
    execute $p$create policy "public-assets: staff delete" on storage.objects for delete to authenticated
      using (bucket_id = 'public-assets' and ((select public.has_permission('content.write'))
             or (select public.has_permission('campaigns.write'))))$p$;
  end if;
end $$;

-- Realtime: customers receive inbox inserts instantly (RLS still applies to the stream).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables
                     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'notifications') then
    alter publication supabase_realtime add table public.notifications;
  end if;
end $$;
